154	    pub fn query_by_file(&self, path: &str) -> Result<Vec<ProvenanceRecord>> {
155	        let mut stmt = self.conn.prepare(
156	            "SELECT id, model_id, model_version, prompt_hash, code_hash, file_path,
157	                    start_line, end_line, contributor_type, attestation_sig,
158	                    timestamp, developer_id, session_id
159	             FROM provenance_records
160	             WHERE file_path = ?1
161	             ORDER BY timestamp DESC",
162	        )?;
163	
164	        let records = stmt
165	            .query_map(params![path], |row| {
166	                Ok(ProvenanceRecord {
167	                    id: Some(row.get(0)?),
168	                    model_id: row.get(1)?,
169	                    model_version: row.get(2)?,
170	                    prompt_hash: row.get(3)?,
171	                    code_hash: row.get(4)?,
172	                    file_path: row.get(5)?,
173	                    start_line: row.get(6)?,
174	                    end_line: row.get(7)?,
175	                    contributor_type: ContributorType::from_str(
176	                        &row.get::<_, String>(8)?,
177	                    ),
178	                    attestation_sig: row.get(9)?,
179	                    timestamp: row.get(10)?,
180	                    developer_id: row.get(11)?,
181	                    session_id: row.get(12)?,
182	                })
183	            })?
184	            .collect::<std::result::Result<Vec<_>, _>>()?;
185	
186	        Ok(records)
187	    }
