189	    pub fn query_by_session(&self, session_id: &str) -> Result<Vec<ProvenanceRecord>> {
190	        let mut stmt = self.conn.prepare(
191	            "SELECT id, model_id, model_version, prompt_hash, code_hash, file_path,
192	                    start_line, end_line, contributor_type, attestation_sig,
193	                    timestamp, developer_id, session_id
194	             FROM provenance_records
195	             WHERE session_id = ?1
196	             ORDER BY timestamp ASC",
197	        )?;
