288	fn audit_log_inner(action: &str, original: &str, rewritten: &str) -> Option<()> {
289	    let home = dirs::home_dir()?;
290	    let dir = home.join(".local").join("share").join("rtk");
291	    std::fs::create_dir_all(&dir).ok()?;
292	    let path = dir.join("hook-audit.log");
293	    let mut file = std::fs::OpenOptions::new()
294	        .create(true)
295	        .append(true)
296	        .open(path)
297	        .ok()?;
298	    let ts = chrono::Local::now().format("%Y-%m-%dT%H:%M:%S");
299	    writeln!(
300	        file,
301	        "{} | {} | {} | {}",
302	        ts,
303	        action,
304	        sanitize_log_field(original),
305	        sanitize_log_field(rewritten)
306	    )
307	    .ok()
308	}
