534	        .filter(|c| !c.is_empty())
535	    {
536	        Some(c) => c.to_string(),
537	        None => return "{}".to_string(),
538	    };
539	
540	    let verdict = permissions::check_command_with_rules(&cmd, deny_rules, ask_rules, allow_rules);
541	    if verdict == PermissionVerdict::Deny {
542	        return "{}".to_string();
543	    }
544	
545	    match get_rewritten(&cmd) {
546	        Some(rewritten) => {
547	            let decision = "allow";
548	            let output = json!({
549	                "continue": true,
550	                "permission": decision,
551	                "updated_input": { "command": rewritten }
552	            });
553	            output.to_string()
554	        }
555	        None => "{}".to_string(),
556	    }
557	}
