559	// ── Provenance capture (diff-on-next-PreToolUse) ───────────────
560	//
561	// Each PreToolUse invocation is a separate OS process. We diff the
562	// working tree against the last snapshot stored in SQLite to detect
563	// what the PREVIOUS tool call changed.
564	
565	fn capture_provenance_best_effort(session_id: &str) {
566	    if std::env::var("RTK_PROVENANCE").as_deref() == Ok("0") {
567	        return;
568	    }
569	    if let Err(e) = capture_provenance(session_id) {
570	        let _ = writeln!(io::stderr(), "[rtk provenance] {e}");
571	    }
572	}
573	
574	fn capture_provenance(session_id: &str) -> Result<()> {
575	    let store = ProvenanceStore::new()?;
576	    let cwd = std::env::current_dir()?;
577	
578	    let tracked_files = collect_tracked_files(&cwd)?;
579	
580	    let mut new_provenance = Vec::new();
581	    for file_path in &tracked_files {
582	        let mtime = file_path
583	            .metadata()
584	            .and_then(|m| m.modified())
585	            .ok();
586	        if let Some(mt) = mtime {
587	            let age = mt.elapsed().unwrap_or_default();
588	            if age.as_secs() > 30 {
589	                continue;
590	            }
591	        }
592	
593	        let rel = file_path
594	            .strip_prefix(&cwd)
595	            .unwrap_or(file_path)
596	            .to_string_lossy()
597	            .replace('\\', "/");
598	
599	        let current_hash = match content_hash::hash_file(file_path) {
600	            Ok(h) => h,
601	            Err(_) => continue,
602	        };
603	
604	        let prev_hash = store.get_snapshot(&rel)?;
605	        if prev_hash.as_deref() == Some(&current_hash) {
606	            continue;
607	        }
608	
609	        if prev_hash.is_some() {
610	            let content = std::fs::read(file_path).unwrap_or_default();
611	            let line_count = content.iter().filter(|&&b| b == b'\n').count() as u32;
612	            let record = provenance::create_signed_record(
613	                &rel,
614	                &content,
615	                1,
616	                line_count.max(1),
617	                session_id,
618	            )?;
619	            new_provenance.push(record);
620	        }
621	
622	        store.save_snapshot(&rel, &current_hash)?;
623	    }
624	
625	    for record in &new_provenance {
626	        store.record_provenance(record)?;
627	    }
628	
629	    Ok(())
630	}
631	
632	fn collect_tracked_files(cwd: &std::path::Path) -> Result<Vec<std::path::PathBuf>> {
633	    let output = std::process::Command::new("git")
634	        .args(["ls-files", "--cached", "--others", "--exclude-standard", "-z"])
635	        .current_dir(cwd)
636	        .output();
637	
638	    let output = match output {
639	        Ok(o) if o.status.success() => o,
640	        _ => return Ok(Vec::new()),
641	    };
642	
643	    let files: Vec<std::path::PathBuf> = output
644	        .stdout
645	        .split(|&b| b == 0)
646	        .filter(|s| !s.is_empty())
647	        .filter_map(|s| std::str::from_utf8(s).ok())
648	        .filter(|s| {
649	            let ext = std::path::Path::new(s)
650	                .extension()
651	                .and_then(|e| e.to_str())
652	                .unwrap_or("");
653	            matches!(
654	                ext,
655	                "rs" | "ts" | "tsx" | "js" | "jsx" | "py" | "go" | "java"
656	                    | "kt" | "swift" | "cs" | "rb" | "sh" | "sql" | "toml"
657	                    | "yaml" | "yml" | "json" | "md"
658	            )
659	        })
660	        .map(|s| cwd.join(s))
661	        .collect();
662	
663	    Ok(files)
664	}
