//! `rtk codeflow cost` — cost attribution report for the current project.
//!
//! Subcommands:
//!   codeflow cost                  — project summary
//!   codeflow cost --by pr          — breakdown by PR
//!   codeflow cost --by dev         — breakdown by developer
//!   codeflow cost --by model       — breakdown by model
//!   codeflow cost --by day         — daily trend
//!   codeflow cost --pr <ref>       — specific PR detail
//!   codeflow cost --json           — machine-readable JSON

use anyhow::{Context, Result};
use colored::Colorize;

use crate::core::cost_store::{CostStore, CostSummary};

pub fn run_cost(
    by: Option<&str>,
    pr: Option<&str>,
    json: bool,
) -> Result<()> {
    let store = CostStore::new().context("failed to open cost store")?;

    // --pr <ref>: single PR detail view
    if let Some(pr_ref) = pr {
        return show_pr_detail(&store, pr_ref, json);
    }

    // --by <grouping>
    match by {
        Some("pr")    => show_by_pr(&store, json),
        Some("dev")   => show_by_dev(&store, json),
        Some("model") => show_by_model(&store, json),
        Some("day")   => show_by_day(&store, json),
        Some(other)   => anyhow::bail!(
            "unknown grouping '{}'. Use: pr, dev, model, day", other
        ),
        None => show_summary(&store, json),
    }
}

// ── Summary view ──────────────────────────────────────────────────────────────

fn show_summary(store: &CostStore, json: bool) -> Result<()> {
    let total = store.total_cost(None)?;
    let by_model = store.summarize_by_model()?;
    let by_pr = store.summarize_by_pr()?;

    if json {
        let out = serde_json::json!({
            "total_cost_usd": total,
            "by_model": by_model,
            "by_pr": by_pr,
        });
        println!("{}", serde_json::to_string_pretty(&out)?);
        return Ok(());
    }

    println!("{}", "Cost Attribution Summary".bold());
    println!("{}", "─".repeat(50));
    println!("  Total: {}", format_usd(total).green().bold());
    println!();

    if !by_model.is_empty() {
        println!("{}", "By Model:".bold());
        for s in &by_model {
            println!(
                "  {:40} {} ({} sessions)",
                truncate(&s.key, 40),
                format_usd(s.total_cost_usd).yellow(),
                s.record_count,
            );
        }
        println!();
    }

    if !by_pr.is_empty() {
        println!("{}", "By PR (top 5):".bold());
        for s in by_pr.iter().take(5) {
            println!(
                "  {:20} {}",
                truncate(&s.key, 20),
                format_usd(s.total_cost_usd).cyan(),
            );
        }
    }

    if by_model.is_empty() && by_pr.is_empty() {
        println!("No cost records found.");
        println!("Run sessions with RTK_COST_TRACK=1 to start recording.");
    }

    Ok(())
}

// ── By-PR breakdown ───────────────────────────────────────────────────────────

fn show_by_pr(store: &CostStore, json: bool) -> Result<()> {
    let summaries = store.summarize_by_pr()?;
    if json {
        println!("{}", serde_json::to_string_pretty(&summaries)?);
        return Ok(());
    }
    print_summary_table("Cost by PR", &summaries, "PR / Ticket");
    Ok(())
}

// ── By-dev breakdown ──────────────────────────────────────────────────────────

fn show_by_dev(store: &CostStore, json: bool) -> Result<()> {
    let summaries = store.summarize_by_dev()?;
    if json {
        println!("{}", serde_json::to_string_pretty(&summaries)?);
        return Ok(());
    }
    print_summary_table("Cost by Developer", &summaries, "Developer");
    Ok(())
}

// ── By-model breakdown ────────────────────────────────────────────────────────

fn show_by_model(store: &CostStore, json: bool) -> Result<()> {
    let summaries = store.summarize_by_model()?;
    if json {
        println!("{}", serde_json::to_string_pretty(&summaries)?);
        return Ok(());
    }
    print_summary_table("Cost by Model", &summaries, "Model");
    Ok(())
}

// ── By-day trend ──────────────────────────────────────────────────────────────

fn show_by_day(store: &CostStore, json: bool) -> Result<()> {
    let summaries = store.summarize_by_day()?;
    if json {
        println!("{}", serde_json::to_string_pretty(&summaries)?);
        return Ok(());
    }

    println!("{}", "Daily Cost Trend".bold());
    println!("{}", "─".repeat(50));

    if summaries.is_empty() {
        println!("No records found.");
        return Ok(());
    }

    let max_cost = summaries
        .iter()
        .map(|s| s.total_cost_usd)
        .fold(0.0_f64, f64::max);

    for s in &summaries {
        let bar_len = if max_cost > 0.0 {
            ((s.total_cost_usd / max_cost) * 30.0) as usize
        } else {
            0
        };
        let bar = "█".repeat(bar_len);
        println!(
            "  {} {} {}",
            s.key.dimmed(),
            bar.cyan(),
            format_usd(s.total_cost_usd).yellow(),
        );
    }
    Ok(())
}

// ── PR detail view ────────────────────────────────────────────────────────────

fn show_pr_detail(store: &CostStore, pr_ref: &str, json: bool) -> Result<()> {
    let records = store.query_by_pr(pr_ref)?;

    if json {
        println!("{}", serde_json::to_string_pretty(&records)?);
        return Ok(());
    }

    if records.is_empty() {
        println!("No cost records found for PR: {}", pr_ref);
        return Ok(());
    }

    let total: f64 = records.iter().map(|r| r.cost_usd).sum();
    let total_in: u64 = records.iter().map(|r| r.input_tokens).sum();
    let total_out: u64 = records.iter().map(|r| r.output_tokens).sum();

    println!("{}", format!("PR {} Cost Detail", pr_ref).bold());
    println!("{}", "─".repeat(60));
    println!("  Total cost:    {}", format_usd(total).green().bold());
    println!("  Input tokens:  {}", fmt_tokens(total_in));
    println!("  Output tokens: {}", fmt_tokens(total_out));
    println!("  Sessions:      {}", records.len());
    println!();

    println!(
        "  {:>24} {:>14} {:>12} {:>12}",
        "TIMESTAMP".bold(),
        "MODEL".bold(),
        "COST".bold(),
        "DEV".bold(),
    );
    println!("  {}", "─".repeat(66));

    for r in &records {
        println!(
            "  {:>24} {:>14} {:>12} {:>12}",
            truncate(&r.timestamp, 24),
            truncate(&r.model_id, 14),
            format_usd(r.cost_usd).yellow().to_string(),
            truncate(&r.developer_id, 12),
        );
    }
    Ok(())
}

// ── Shared table renderer ─────────────────────────────────────────────────────

fn print_summary_table(title: &str, summaries: &[CostSummary], key_label: &str) {
    println!("{}", title.bold());
    println!("{}", "─".repeat(60));

    if summaries.is_empty() {
        println!("No records found.");
        return;
    }

    println!(
        "  {:30} {:>12} {:>10} {:>14}",
        key_label.bold(),
        "COST".bold(),
        "SESSIONS".bold(),
        "TOKENS (in+out)".bold(),
    );
    println!("  {}", "─".repeat(70));

    for s in summaries {
        let tokens = fmt_tokens(s.input_tokens + s.output_tokens);
        println!(
            "  {:30} {:>12} {:>10} {:>14}",
            truncate(&s.key, 30),
            format_usd(s.total_cost_usd).yellow().to_string(),
            s.record_count,
            tokens,
        );
    }
}

// ── Formatting helpers ────────────────────────────────────────────────────────

fn format_usd(amount: f64) -> String {
    format!("${:.4}", amount)
}

fn fmt_tokens(n: u64) -> String {
    if n >= 1_000_000 {
        format!("{:.1}M", n as f64 / 1_000_000.0)
    } else if n >= 1_000 {
        format!("{:.1}K", n as f64 / 1_000.0)
    } else {
        format!("{}", n)
    }
}

fn truncate(s: &str, max: usize) -> String {
    if s.len() <= max {
        s.to_string()
    } else {
        let end = s
            .char_indices()
            .take_while(|(i, _)| *i < max.saturating_sub(2))
            .last()
            .map(|(i, c)| i + c.len_utf8())
            .unwrap_or(0);
        format!("{}..", &s[..end])
    }
}

#[cfg(test)]
