    }

    #[test]
    fn fmt_tokens_scales_correctly() {
        assert_eq!(fmt_tokens(500), "500");
        assert_eq!(fmt_tokens(1_500), "1.5K");
        assert_eq!(fmt_tokens(2_000_000), "2.0M");
