    fn truncate_short_string_unchanged() {
        assert_eq!(truncate("hello", 10), "hello");
    }

    #[test]
    fn truncate_long_string_gets_ellipsis() {
        let result = truncate("abcdefghijk", 8);
        assert!(result.len() <= 8);
        assert!(result.ends_with(".."));
    }

    #[test]
    fn run_cost_unknown_by_errors() {
        // Build a temp store and verify unknown grouping returns Err
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("cost.db");
        std::env::set_var("RTK_COST_DB", db_path.to_str().unwrap());
        let result = run_cost(Some("unknown_grouping"), None, false);
        std::env::remove_var("RTK_COST_DB");
        assert!(result.is_err());
    }

