    fn run_cost_summary_json_empty_store() {
        let dir = tempfile::tempdir().unwrap();
        let db_path = dir.path().join("cost.db");
        std::env::set_var("RTK_COST_DB", db_path.to_str().unwrap());
        let result = run_cost(None, None, true);
        std::env::remove_var("RTK_COST_DB");
        assert!(result.is_ok());
    }
