// ── PR metadata capture ────────────────────────────────────────
//
// Detect the current PR/feature context from env vars or branch name (<1ms,
// no network calls) and write it to a per-session sidecar file. The cost
// attribution command reads these files to link sessions to PRs.

fn capture_pr_metadata_best_effort(session_id: &str) {
    if std::env::var("RTK_PROVENANCE").as_deref() == Ok("0") {
        return;
    }
    if let Err(e) = capture_pr_metadata(session_id) {
        let _ = writeln!(io::stderr(), "[rtk pr-meta] {e}");
    }
}

fn capture_pr_metadata(session_id: &str) -> anyhow::Result<()> {
    let pr_ref = pr_linker::detect_pr_ref();
    let feature_tag = pr_linker::detect_feature_tag();

    // Nothing to record if both are absent
    if pr_ref.is_none() && feature_tag.is_none() {
        return Ok(());
    }

    let data_dir = dirs::data_local_dir()
        .unwrap_or_else(|| std::path::PathBuf::from("."))
        .join(crate::core::constants::RTK_DATA_DIR)
        .join("session-meta");

    std::fs::create_dir_all(&data_dir)?;

    let meta_path = data_dir.join(format!("{}.json", session_id));

    // Skip write if file already exists (first hook call wins; branch won't change
    // mid-session and re-writing on every tool call wastes I/O).
    if meta_path.exists() {
        return Ok(());
    }

    let meta = serde_json::json!({
        "session_id": session_id,
        "pr_ref": pr_ref,
        "feature_tag": feature_tag,
        "captured_at": chrono::Utc::now().to_rfc3339(),
    });

    std::fs::write(&meta_path, serde_json::to_string(&meta)?)?;
    Ok(())
}

