69	/// Get git-staged files via `git diff --staged --name-only`.
70	fn collect_staged_files() -> Result<Vec<PathBuf>> {
71	    let output = std::process::Command::new("git")
72	        .args(["diff", "--staged", "--name-only"])
73	        .output();
74	
75	    match output {
76	        Ok(out) if out.status.success() => {
77	            let files: Vec<PathBuf> = String::from_utf8_lossy(&out.stdout)
78	                .lines()
79	                .filter(|l| !l.is_empty())
80	                .map(PathBuf::from)
81	                .filter(|p| p.exists())
82	                .collect();
83	            Ok(files)
84	        }
85	        Ok(_) => {
86	            // git ran but returned non-zero (e.g., not a git repo) — scan nothing
87	            eprintln!("[rtk quality] warning: not in a git repo, use --all to scan all files");
88	            Ok(vec![])
89	        }
90	        Err(e) => {
91	            eprintln!("[rtk quality] warning: git not available: {}", e);
92	            Ok(vec![])
93	        }
94	    }
95	}
