97	/// Walk the project directory and collect all scannable files.
98	fn collect_all_project_files() -> Result<Vec<PathBuf>> {
99	    let ignore_dirs = ["node_modules", "vendor", ".git", "target", "dist", "build"];
100	    let scan_exts = ["js", "ts", "jsx", "tsx", "mjs", "cjs", "py", "toml", "rs"];
101	
102	    let mut files = Vec::new();
103	    for entry in walkdir::WalkDir::new(".")
104	        .follow_links(false)
105	        .into_iter()
106	        .filter_entry(|e| {
107	            let name = e.file_name().to_string_lossy();
108	            !ignore_dirs.iter().any(|d| name == *d)
109	        })
110	        .filter_map(|e| e.ok())
111	    {
112	        if !entry.file_type().is_file() {
113	            continue;
114	        }
115	        let ext = entry
116	            .path()
117	            .extension()
118	            .and_then(|e| e.to_str())
119	            .unwrap_or("");
120	        if scan_exts.contains(&ext) {
121	            files.push(entry.path().to_path_buf());
122	        }
123	    }
124	    Ok(files)
125	}
