150	    let high = result.stats.findings_by_severity.get("high").copied().unwrap_or(0);
151	    let medium = result.stats.findings_by_severity.get("medium").copied().unwrap_or(0);
152	    let low = result.stats.findings_by_severity.get("low").copied().unwrap_or(0);
153	
154	    if result.passed {
155	        println!(
156	            "{}",
157	            format!(
