159	                result.stats.files_scanned, result.findings.len(), critical, high, medium, low
160	            )
161	            .green()
162	            .bold()
163	        );
164	    } else {
165	        let blocking: usize = result
166	            .findings
167	            .iter()
168	            .filter(|f| config.is_blocking(f.severity))
169	            .count();
170	        println!(
171	            "{}",
172	            format!(
173	                "GATE FAILED: {} critical, {} high — {} blocking finding(s) in {} file(s)",
174	                critical, high, blocking, result.stats.files_scanned
175	            )
176	            .red()
177	            .bold()
178	        );
179	    }
180	}
