185	        Severity::High => format!("[HIGH]").yellow().bold().to_string(),
186	        Severity::Medium => format!("[MEDIUM]").cyan().to_string(),
187	        Severity::Low => format!("[LOW]").white().dimmed().to_string(),
188	    };
189	
190	    let check_label = format!("[{}]", f.check_type.as_str()).dimmed();
191	
192	    let location = if f.line > 0 {
